def bfs(graph, n, alpha, used, color):
    """Breadth first search on a graph!"""
    q = deque([alpha])

    used[alpha] = True
    z, o = 0, 0
    while q:
        v = q.popleft()
        if color[v] == -1:
            color[v] = 0
            z += 1
        for u in graph[v]:
            if not used[u]:
                used[u] = True
                q.append(u)
            if color[u] == color[v]:return False
            if color[u] == -1:
                if color[v] == 1:z+=1
                else: o += 1
            color[u] = (color[v] + 1) % 2
    return (used, color, z, o)

def shortest_path(graph, alpha, omega):
    """Returns the shortest path between two vertices!"""
    used, dist, parents = bfs(graph, alpha)
    if not used[omega]:
        return []
    path = [omega]
    v = omega
    while parents[v] != -1:
        path += [parents[v]]
        v = parents[v]
    return path[::-1]


