# https://github.com/cheran-senthil/PyRival/blob/master/pyrival/misc/bootstrap.py
def bootstrap(f, stack=[]):
    def wrappedfunc(*args, **kwargs):
        if stack:
            return f(*args, **kwargs)
        else:
            to = f(*args, **kwargs)
            while True:
                if type(to) is GeneratorType:
                    stack.append(to)
                    to = next(to)
                else:
                    stack.pop()
                    if not stack:
                        break
                    to = stack[-1].send(to)
            return to

    return wrappedfunc


def bfs(g, source):
    q = deque()
    dist = {}
    q.append(source)
    dist[source] = 0
    while q:
        node = q.popleft()
        assert node in dist
        d = dist[node]
        for nbr in g[node]:
            if nbr not in dist:
                q.append(nbr)
                dist[nbr] = d + 1
    return dist


def findCycle(source, graph):
    # Find a short cycle
    @bootstrap
    def f(path, depth):
        # print(path, depth)
        cycleDepth = -1
        for nbr in graph[path[-1]]:
            if len(path) >= 2 and nbr == path[-2]:
                continue
            if nbr in depth:
                cycleDepth = max(cycleDepth, depth[nbr])

        if cycleDepth != -1:
            yield path[cycleDepth:]
            return
        for nbr in graph[path[-1]]:
            if len(path) >= 2 and nbr == path[-2]:
                continue
            depth[nbr] = depth[path[-1]] + 1
            path.append(nbr)
            ret = yield f(path, depth)
            if ret:
                yield ret
                return
            path.pop()
            del depth[nbr]
        yield None
        return

    return f([source], {source: 0})


def solve(N, M, K, edges):
    graph = [[] for i in range(N)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    cycle = findCycle(0, graph)

    independentLen = (K + 1) // 2
    if cycle:
        # print(cycle)
        if len(cycle) <= K:
            ans = cycle
            return "2" + "\n" + str(len(ans)) + "\n" + " ".join(str(x + 1) for x in ans)
        else:

            ans = []
            for i in range(independentLen):
                ans.append(cycle[i * 2])
            return "1" + "\n" + " ".join(str(x + 1) for x in ans)

    else:
        # No cycle means tree

        dist = bfs(graph, 0)
        evenCount = 0
        oddCount = 0
        for v, d in dist.items():
            if d % 2 == 0:
                evenCount += 1
            else:
                oddCount += 1
        mod = 0
        if evenCount >= independentLen:
            mod = 0
        elif oddCount >= independentLen:
            mod = 1
        else:
            return -1
        ans = []
        for v, d in dist.items():
            if d % 2 == mod:
                ans.append(v)

                if len(ans) == independentLen:
                    break
        return "1" + "\n" + " ".join(str(x + 1) for x in ans)


