def scc_dfs1(s, links, status, postorder):
    stack = [s]
    status[s] = 0
    while stack:
        v = stack[-1]
        limit = len(links[v])
        while status[v] < limit:
            u = links[v][status[v]]
            status[v] += 1
            if status[u] != -1:
                continue
            stack.append(u)
            status[u] = 0
            break
        else:
            stack.pop()
            postorder.append(v)
    return


def scc_dfs2(s, rev_links, status):
    stack = [s]
    status[s] = -1
    scc = [s]
    while stack:
        v = stack.pop()
        for u in rev_links[v]:
            if status[u] != -1:
                stack.append(u)
                status[u] = -1
                scc.append(u)
    return scc


def strongly_connected_components(n, links, rev_links):
    status = [-1] * n
    postorder = []

    for v in range(n):
        if status[v] != -1:
            continue
        scc_dfs1(v, links, status, postorder)

    postorder.reverse()
    sccs = []

    for v in postorder:
        if status[v] == -1:
            continue
        sccs.append(scc_dfs2(v, rev_links, status))

    return sccs


