def dfs(g, u, visited, call_stack):
    visited[u] = True
    call_stack.add(u)
    for v in g[u]:
        if v in call_stack:
            return [u, v]
        if not visited[v]:
            d = dfs(g, v, visited, call_stack)
            call_stack.discard(v)
            if d is not None:
                return [u] + d
    return None


def find_cycle(g, n):
    visited = [False] * n
    d = None
    for i in range(n):
        if not visited[i]:
            call_stack = set()
            d = dfs(g, i, visited, call_stack)
            if d is not None:
                break
    return d


